definition.script:
pipeline {
    agent any

    tools {
        maven 'maven3.9'
        jdk 'jdk17'
    }

    environment{
        SCANNER_HOME = tool 'sonar-scanner'
    }

    stages {
        stage('Git Checkout') {
            steps {
                git branch: 'main', url: 'https://github.com/sandhya-en/Boardgame.git'
            }
        }
         stage('Compile') {
            steps {
                echo 'mvn compile'
            }
        }
         stage('Test') {
            steps {
                echo 'mvn test'
            }
        }

        stage('Build') {
            steps {
                echo 'mvn clean package'
            }
        }

        stage('SonarQube Analysis') {
            steps {
                withSonarQubeEnv('sonarqube'){
                    sh ''' $SCANNER_HOME/bin/sonar-scanner -Dsonar.projectname=BoardGame\
                             -Dsonar.projectkey=Boardgame -Dsonar.java.binaries=target'''
                }
            }
        }
        stage('Quality-Gate') {
            steps {
                timeout(time: 1, unit: 'HOURS') {
                waitForQualityGate abortPipeline: false, credentialsId: 'sonarqube-cred'
            }

        }
    }
}
}
